// 出牌與回合系統
// battle.js
import { applyCardEffect } from "./applyCardEffect.js";
import { drawCards } from "./utils.js";
import { enemyAI } from "./enemy.js";

// 出牌
export function playCard(player, enemy, card, logFn, showMsg, onHit) {
  if (player.gameOver) return;  // 遊戲已結束，不允許出牌
  const cardIndex = player.hand.findIndex(c => c.uid == card.uid); 
  if ( cardIndex == -1)  {
    console.warn("ID/UID有問題", card.id, card.uid);
    return;
    }

  if ((card.costAP || 0)> player.ap) {
    showMsg("行動值不足！");
    return;
  }
  if ((card.costMP || 0) > player.mp) {
    showMsg("魔力不足!");
    return;
  }
  if (card.desc.includes('回復')) {
    if (player.hp == player.maxHP) {
      showMsg("生命值已滿");
      return;
    }
  }

  player.ap -= card.costAP || 0;
  player.mp -= card.costMP || 0;

  logFn( player.name + "使用卡牌：" + card.name);

  applyCardEffect(player, enemy, card, logFn, onHit);

  player.hand.splice(cardIndex, 1);
  player.discard.push(card);

  console.log("卡牌進入棄牌堆(ID)：", card.id, card.uid);
}

// 下一回合
export async function nextTurn(player, enemy, logFn, onHit) {
    logFn("敵人回合開始");

    processDebuffs(enemy, logFn, onHit);

    if (enemy.hp <= 0) return;

    enemy.ap = 3;
    enemy.mp = 3;

    drawCards(enemy, 3);[]
    
    await enemyAI(player, enemy, logFn, onHit);
    enemy.buff = 0;
    startPlayerTurn(player, enemy, logFn, onHit);
}

// 玩家回合開始
export function startPlayerTurn(player, enemy, logFn, onHit) {
    logFn("玩家回合開始");

    processDebuffs(player, logFn, onHit);

    if (player.hp <= 0) return;

    console.log(player.deck);

  if (player.name === "abisu") {
        player.ap = 99;
        player.mp = 99;
    } else {
        switch (player.job) {
            case "warrior":
                player.ap = 3; 
                player.mp = 0; 
                break;
            case "mage":
                player.ap = 0; 
                player.mp = 4;
                break;
            case "archer":
                player.ap = 5;
                player.mp = 0; 
                break;
            default:
                player.ap = 3;
                player.mp = 3;
        }
    }

    // 抽牌
    drawCards(player, 3);

    console.log(player.hand);
}

// 結束玩家回合
export async function endPlayerTurn(player, enemy, logFn, onHit) {
  // 將剩餘手牌放入棄牌堆
  while (player.hand.length > 0) {
    const card = player.hand.pop();

    player.discard.push(card);

    console.log("剩下的卡牌進入棄牌堆(ID)：", card.id);
  }
  player.buff = 0;

  await nextTurn(player, enemy, logFn, onHit);
}

function processDebuffs(character, logFn, onHit) {
  if (!character.debuffs || character.debuffs.length === 0) return;

    logFn(`--- 結算 ${character.name} 的狀態效果 ---`);

    character.debuffs = character.debuffs.filter(debuff => {
        
        if (debuff.value > 0) {
            character.hp -= debuff.value;

            if (character.hp < 0) character.hp = 0;
            
            logFn(`${character.name} 因 [${debuff.name}] 受到 ${debuff.value} 點傷害`);
            
            if (onHit) onHit(character, 'damage', debuff.value); 
        }

        debuff.round--;

        if (debuff.round <= 0) {
            logFn(`[${debuff.name}] 效果結束了`);
            return false; 
        }
        return true; 
    });
}