<template>
  <div 
    v-if="active" 
    class="fixed inset-0 z-[9999] overflow-hidden pointer-events-auto transition-opacity duration-300"
    :class="rect.width > 0 ? 'opacity-100' : 'opacity-0'"
    @click="next">
    <div 
      class="absolute border-2 border-yellow-400 rounded-lg transition-all duration-300 pointer-events-none shadow-[0_0_0_9999px_rgba(0,0,0,0.8)]"
      :style="highlightStyle"
    >
      <div class="absolute inset-0 bg-white/10 animate-pulse"></div>
    </div>

    <div 
      class="absolute p-6 bg-gray-800 border-2 border-yellow-500 rounded-2xl shadow-2xl text-white w-80 transition-all duration-500"
      :style="tooltipStyle"
    >
      <h3 class="text-yellow-400 font-bold text-xl mb-2">💡 教學指南</h3>
      <p class="text-gray-200 leading-relaxed">{{ currentStep.text }}</p>
      <div class="mt-4 flex justify-between items-center text-sm text-gray-400">
        <span>點擊任意處繼續 ({{ stepIndex + 1 }}/{{ totalSteps }})</span>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    active: Boolean,
    stepIndex: Number,
    steps: Array
  },
  mounted() {
    if (this.active) {
        this.updateRect();
    }
  },
  data() {
    return {
      rect: { top: 0, left: 0, width: 0, height: 0 }
    }
  },
  computed: {
    currentStep() { return this.steps[this.stepIndex] || {}; },
    totalSteps() { return this.steps.length; },
    highlightStyle() {
      return {
        top: `${this.rect.top - 8}px`,
        left: `${this.rect.left - 8}px`,
        width: `${this.rect.width + 16}px`,
        height: `${this.rect.height + 16}px`
      }
    },
    tooltipStyle() {
      // 根據亮框位置自動調整文字框出現在上方或下方
      const isTopHalf = this.rect.top < window.innerHeight / 2;
      return {
        top: isTopHalf ? `${this.rect.top + this.rect.height + 40}px` : `${this.rect.top - 200}px`,
        left: `${Math.min(window.innerWidth - 340, Math.max(20, this.rect.left + (this.rect.width / 2) - 160))}px`
      }
    }
  },
  watch: {
    // 當步驟改變時，重新計算目標元素的位置
    stepIndex() { this.updateRect(); },
    active(val) { if(val) this.updateRect(); }
  },
  methods: {
    updateRect() {
      this.$nextTick(() => {
        const el = document.getElementById(this.currentStep.targetId);
        if (el) {
          const box = el.getBoundingClientRect();
          
          // 如果寬度為 0，代表元素還在變動或未渲染
          if (box.width === 0) {
            setTimeout(() => this.updateRect(), 100);
            return;
          }
          this.rect = box;
        } else {
          // 如果找不到元素，100ms 後重試（針對剛切換畫面時 DOM 未掛載的情況）
          setTimeout(() => this.updateRect(), 100);
        }
      });
    },
    next() { 
      // 防止在位置還沒抓到（隱形狀態）時誤點
      if (this.rect.width === 0) return; 
      this.$emit('next'); 
    }
  }
}
</script>