function generateDesc(id, potions) {
    switch(true) {
        case id.includes("heal"):
            return `使用後回復${potions.heal}點生命，持續${potions.buffcount}回合`;
        case id.includes("power"):
            return `使用後增加${potions.power}點攻擊力，持續${potions.buffcount}回合`;
        default:
            return ";"
    }   
}