<template>
  <!-- 底部卡牌區 (手牌、牌庫、棄牌) -->
  <footer class="mt-4 bg-gray-800 p-4 rounded-lg shadow-2xl h-64">
    <div class="flex justify-between items-start mb-3">
      <!-- 牌庫區 -->
      <div id="card-deck" class="relative top-6 flex flex-col items-center">
        <div class="card-deck bg-gray-600 border-gray-400 flex items-center justify-center text-4xl font-extrabold">
          <span class="-translate-y-[45px] relative">{{ deckCount }}</span>
        </div>
        <p class="mt-1 text-sm text-gray-400">牌庫</p>
      </div>

      <!-- 手牌區 - 使用 Card.vue 渲染 -->
      <div id="hand-area" class="relative flex-1 h-[225px] flex justify-center items-end">
        <GameCard 
          v-for="(card, index) in hand" 
          :key="card.uid"
          :card="card"
          :style="getCardStyle(index, hoverIndex === index)"
          @mouseenter="hoverIndex = index"
          @mouseleave="hoverIndex = -1"
          @play="handlePlay"
        />
      </div>

      <!-- 棄牌區 -->
      <div class="relative top-6 flex flex-col items-center">
        <div id="card-discard" class="card-deck bg-gray-700 border-gray-500 flex items-center justify-center text-4xl font-extrabold opacity-75">
        <span class="-translate-y-[45px] relative">{{ discardCount }}</span>
        </div>
        <p class="mt-1 text-sm text-gray-400">棄牌區</p>

        <!-- 回合結束按鈕 -->
        <button id="end-turn-btn" @click="$emit('endTurn')" class="translate-x-[-130px] relative bottom-6 mt-2 px-3 py-2 bg-red-600 hover:bg-red-700 text-white font-bold rounded-xl shadow-lg transition transform hover:scale-105">
          結束回合
        </button>

      </div>
    </div>
  </footer>
</template>

<script>
import GameCard from "./Card.vue";

export default {
  name: "PlayerHand",
  components: { GameCard },
  props: {
    hand: Array,
    deckCount: Number,
    discardCount: Number
  },
  data() {
    return {
      hoverIndex: -1
    }
  },
  watch: {
    hand: {
      handler() {
        this.hoverIndex = -1;
      },
      deep: true
    }
  },
  methods: {
    handlePlay(card) {
      this.$emit("playCard", card);
    },
    getCardStyle(index) {
      const N = this.hand.length;
      const mid = N > 1 ? (N - 1) / 2 : 0;
      const maxAngle = Math.min(30, 15 * N / 5);

      // 判斷是否 hover
      const isHover = this.hoverIndex === index;

      const angle = isHover ? 0 : N > 1 ? ((index - mid) / mid) * maxAngle : 0;
      const offsetY = N > 1 ? -Math.cos((index - mid) / mid * Math.PI / 2) * 20 : 0;
      const offsetX = (index - mid) * 130;

      const scale = isHover ? 2 : 1;
      const hoverY = isHover ? -120 : 0;

      // hover 的牌 zIndex 最大，其餘依 index 排序
      const z = isHover ? N + 1 : index;

      return {
          transform: `translate(${offsetX}px, ${offsetY + hoverY}px) rotate(${angle}deg) scale(${scale})`,
          zIndex: z
      };
    }

  }
};
</script>

<style scoped>
#hand-area {
  perspective: 500px;
}

.card {
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
    position: absolute;
    bottom: 0;
    transition: transform 0.3s;
}

.card-deck {
    background-image: url("../assets/images/card/cardback.webp");
    background-size: cover;
    background-position: center;
    width: 120px;
    height: 160px;
    border-width: 2px;
    border-radius: 0.5rem;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
}

.card:hover {
  cursor:pointer;
}

@media (max-width: 768px) {
    .card {
        width: 90px;
        height: 120px;
    }
    .card-deck {
        width: 90px;
        height: 120px;
    }
}
</style>