// src/js/systems/relics.js

import { equipments } from "../data/items.js";

// 定義每個裝備的效果邏輯
const RELIC_EFFECTS = {
  // === ❤️ 生命之心 ===
  life_heart: {
    // 事件：當血量變化時
    onHpChange: (player, context) => {
      const { newHp, addLog, triggerEffect } = context;
      
      // 邏輯：血量 < 30% 且 本場戰鬥尚未觸發
      if (!player.lifeHeartTriggered && newHp < player.maxHP * 0.3) {
        
        const healAmount = equipments.life_heart.heal;

        player.hp = Math.min(player.maxHP, player.hp + healAmount);
        
        player.lifeHeartTriggered = true; // 標記已觸發
        
        addLog(`❤️ 生命之心：瀕死爆發！回復 ${healAmount} 點生命`);
        triggerEffect(player, 'heal', healAmount);
      }
    }
  },

  // === 🛡️ 森林古盾 ===
  forest_shield: {
    // 事件：回合開始時
    onTurnStart: (player, context) => {
      const { turn, addLog, triggerEffect } = context;
      
      let armorGain = equipments.forest_shield.def;
      if (turn <= 5) {
        armorGain += 2;
      }
      player.defend += armorGain;
      
      addLog(`🛡️ 森林古盾：獲得 ${armorGain} 點護甲`);
      triggerEffect(player, 'armor', armorGain);
    }
  },

  // === 🌿 翠綠輪環 ===
  emerald_circle: {
    // 事件：回合開始時
    onTurnStart: (player, context) => {
      const { tookDamageThisRound, addLog, triggerEffect } = context;

      if (!tookDamageThisRound) {
        const healAmount = equipments.emerald_circle.heal;
        player.hp = Math.min(player.maxHP, player.hp + healAmount);
        addLog(`🌿 翠綠輪環：氣息平穩，回復 ${healAmount} 點生命`);
        triggerEffect(player, 'heal', healAmount);
      } else {
        const armorAmount = 2;
        player.armor += armorAmount;
        addLog(`🌿 翠綠輪環：受到威脅，獲得 ${armorAmount} 點護甲`);
        triggerEffect(player, 'armor', armorAmount);
      }
    }
  }
};

/**
 * 統一觸發裝備特效的入口函數
 *這就是您想要的 "applyRelicEffect"
 * @param {Object} player 玩家物件
 * @param {String} eventType 事件類型 ('onTurnStart' | 'onHpChange')
 * @param {Object} context 額外的參數 (如 turn, addLog, triggerEffect 等)
 */
export function applyRelicEffect(player, eventType, context) {
  if (!player.backpack) return;

  // 遍歷背包裡的所有物品 ID
  player.backpack.forEach(itemId => {
    const relic = RELIC_EFFECTS[itemId];
    
    // 如果這個物品有定義對應事件的特效，就執行它
    if (relic && relic[eventType]) {
      relic[eventType](player, context);
    }
  });
}